#!/usr/bin/env python3
"""Minimal strings(1) replacement for firmware analysis on Windows."""
import sys, re

def strings(path, minlen=5, encoding='ascii'):
    with open(path, 'rb') as f:
        data = f.read()
    if encoding == 'ascii':
        pat = <访问令牌_01>'[\x20-\x7e]{%d,}' % minlen)
        for m in pat.finditer(data):
            yield m.group().decode()
    else:  # utf-16le
        pat = <访问令牌_01>'(?:[\x20-\x7e]\x00){%d,}' % minlen)
        for m in pat.finditer(data):
            yield m.group().decode('utf-16le')

if __name__ == '__main__':
    args = [a for a in sys.argv[1:] if not a.startswith('-')]
    enc = 'utf16' if '-el' in sys.argv else 'ascii'
    minlen = 5
    for a in sys.argv[1:]:
        if a.startswith('-n'):
            minlen = int(a[2:] or sys.argv[sys.argv.index(a)+1])
    for path in args:
        for s in strings(path, minlen, enc):
            print(s)

